-- six-month-plan: full schema for a fresh Supabase project.
-- Generated by scripts/build-setup-sql.sh from supabase/migrations/*.sql (26 files).
-- Paste the whole file into Supabase → SQL Editor and run it once. For an existing project,
-- run only the migrations you haven't yet (each is safe to run again).
-- Reminders/digests cron is separate: supabase/cron.sql.

-- ======================================================================
-- 20261016000000_initial_schema.sql
-- ======================================================================
-- Six-Month Plan: initial schema
-- Every table is owned by one user (user_id defaults to the signed-in user)
-- and protected by row-level security. History is never overwritten:
-- targets and schedules get new rows with effective dates.

create extension if not exists pgcrypto;

-- ---------- Helpers ----------
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------- Planning ----------
create table public.profiles (
  user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,
  display_name text not null default '',
  timezone text not null default 'America/New_York',
  units text not null default 'lb' check (units in ('lb', 'kg')),
  -- minutes available per weekday, Monday first
  available_minutes int[] not null default '{150,150,150,150,150,180,60}',
  welcome_dismissed_on date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null,
  start_date date not null,
  end_date date not null,
  block_days int not null default 28 check (block_days between 7 and 56),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date > start_date)
);

create table public.goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  title text not null,
  type text not null check (type in ('number', 'practice', 'finish')),
  why text not null default '',
  done_means text not null default '',
  unit text,
  baseline_value numeric,
  baseline_date date,
  target_value numeric,
  target_date date,
  color text not null default '#0E6B61',
  measurement_type_id uuid,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.plan_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  plan_id uuid not null references public.plans(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (plan_id, goal_id)
);

create table public.goal_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  target_date date not null,
  target_value numeric not null,
  effective_from date not null default current_date,
  superseded_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.milestones (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  title text not null,
  due_date date not null,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------- Doing ----------
create table public.actions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  title text not null,
  kind text not null default 'check' check (kind in ('check', 'count', 'minutes', 'workout', 'study')),
  planned_minutes int not null default 0 check (planned_minutes >= 0),
  planned_count int check (planned_count is null or planned_count > 0),
  min_label text not null default '',
  min_minutes int,
  min_count int,
  priority boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.action_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  action_id uuid not null references public.actions(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (action_id, goal_id)
);

create table public.action_schedules (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  action_id uuid not null references public.actions(id) on delete cascade,
  rule text not null check (rule in ('days', 'per_week')),
  -- ISO weekdays, 1 = Monday ... 7 = Sunday
  days int[] not null default '{}',
  per_week int check (per_week is null or per_week between 1 and 14),
  effective_from date not null,
  effective_to date,
  created_at timestamptz not null default now()
);

create table public.sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  action_id uuid references public.actions(id) on delete set null,
  week_start date not null,
  slot int not null default 0,
  date date, -- null = not placed on a day yet
  title text not null,
  priority boolean not null default false,
  planned_minutes int not null default 0,
  planned_count int,
  status text not null default 'planned'
    check (status in ('planned', 'done', 'partial', 'minimum', 'skipped', 'moved')),
  actual_minutes int,
  actual_count int,
  note text not null default '',
  obstacles text[] not null default '{}',
  origin text not null default 'scheduled' check (origin in ('scheduled', 'oneoff', 'unplanned')),
  source text not null default 'manual',
  moved_from uuid references public.sessions(id) on delete set null,
  logged_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- One session per action, week, origin and slot: generating a week twice (or on two
-- devices) never duplicates. One-off tasks have no action, so they never collide.
alter table public.sessions
  add constraint sessions_slot_unique unique (user_id, action_id, week_start, origin, slot);
create index sessions_by_date on public.sessions (user_id, date);
create index sessions_by_week on public.sessions (user_id, week_start);

create table public.workout_sets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  session_id uuid not null references public.sessions(id) on delete cascade,
  exercise text not null,
  set_no int not null,
  weight numeric,
  reps int,
  done boolean not null default false,
  created_at timestamptz not null default now()
);

-- ---------- Results ----------
create table public.measurement_types (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null,
  unit text not null default '',
  cadence_days int not null default 7 check (cadence_days between 1 and 90),
  goal_id uuid references public.goals(id) on delete set null,
  archived_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.goals
  add constraint goals_measurement_type_fk
  foreign key (measurement_type_id) references public.measurement_types(id) on delete set null;

create table public.measurements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  type_id uuid not null references public.measurement_types(id) on delete cascade,
  value numeric not null,
  measured_on date not null,
  source text not null default 'manual',
  note text not null default '',
  created_at timestamptz not null default now()
);
create index measurements_by_type on public.measurements (user_id, type_id, measured_on);

-- ---------- Reviewing ----------
create table public.week_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  week_start date not null,
  available_minutes int not null default 0,
  planned_minutes int not null default 0,
  saved_at timestamptz not null default now(),
  unique (user_id, week_start)
);

create table public.reviews (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  kind text not null check (kind in ('weekly', 'block', 'quarter', 'retro')),
  period_start date not null,
  period_end date not null,
  status text not null default 'done' check (status in ('draft', 'done')),
  went_well text not null default '',
  got_in_way text not null default '',
  change_next text not null default '',
  obstacles text[] not null default '{}',
  actions_done numeric not null default 0,
  actions_planned int not null default 0,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.change_log (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  entity text not null,
  entity_id uuid not null,
  summary text not null,
  old_value jsonb,
  new_value jsonb,
  effective_from date not null,
  review_id uuid references public.reviews(id) on delete set null,
  created_at timestamptz not null default now()
);

-- ---------- updated_at triggers ----------
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();
create trigger plans_touch before update on public.plans for each row execute function public.touch_updated_at();
create trigger goals_touch before update on public.goals for each row execute function public.touch_updated_at();
create trigger milestones_touch before update on public.milestones for each row execute function public.touch_updated_at();
create trigger actions_touch before update on public.actions for each row execute function public.touch_updated_at();
create trigger sessions_touch before update on public.sessions for each row execute function public.touch_updated_at();

-- ---------- Row-level security: only the owner sees and changes a row ----------
do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'plans', 'goals', 'plan_goals', 'goal_targets', 'milestones',
    'actions', 'action_goals', 'action_schedules', 'sessions', 'workout_sets',
    'measurement_types', 'measurements', 'week_plans', 'reviews', 'change_log'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format(
      'create policy %I on public.%I for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid())',
      t || '_owner', t
    );
  end loop;
end;
$$;

-- ---------- Weekly review: one transaction ----------
-- Payload shape:
-- {
--   "review": { id, kind, period_start, period_end, went_well, got_in_way, change_next,
--               obstacles: [], actions_done, actions_planned },
--   "schedule_changes": [ { end_schedule_id, end_on, new_schedule: {id, action_id, rule, days, per_week, effective_from},
--                           summary, old_value, new_value } ],
--   "action_changes":   [ { action_id, min_label, min_minutes, min_count, summary, old_value, new_value } ],
--   "week_plan": { id, week_start, available_minutes, planned_minutes },
--   "sessions":  [ session rows for next week ],
--   "measurements": [ measurement rows ]
-- }
create or replace function public.complete_weekly_review(payload jsonb)
returns uuid
language plpgsql
security invoker
as $$
declare
  r jsonb := payload -> 'review';
  review_id uuid := coalesce((r ->> 'id')::uuid, gen_random_uuid());
  item jsonb;
  ns jsonb;
begin
  insert into public.reviews (id, kind, period_start, period_end, status, went_well, got_in_way,
                              change_next, obstacles, actions_done, actions_planned, completed_at)
  values (
    review_id,
    r ->> 'kind',
    (r ->> 'period_start')::date,
    (r ->> 'period_end')::date,
    'done',
    coalesce(r ->> 'went_well', ''),
    coalesce(r ->> 'got_in_way', ''),
    coalesce(r ->> 'change_next', ''),
    coalesce(array(select jsonb_array_elements_text(r -> 'obstacles')), '{}'),
    coalesce((r ->> 'actions_done')::numeric, 0),
    coalesce((r ->> 'actions_planned')::int, 0),
    now()
  );

  for item in select * from jsonb_array_elements(coalesce(payload -> 'measurements', '[]'::jsonb)) loop
    insert into public.measurements (id, type_id, value, measured_on, source, note)
    values ((item ->> 'id')::uuid, (item ->> 'type_id')::uuid, (item ->> 'value')::numeric,
            (item ->> 'measured_on')::date, 'manual', coalesce(item ->> 'note', ''));
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'schedule_changes', '[]'::jsonb)) loop
    update public.action_schedules
       set effective_to = (item ->> 'end_on')::date
     where id = (item ->> 'end_schedule_id')::uuid;
    ns := item -> 'new_schedule';
    insert into public.action_schedules (id, action_id, rule, days, per_week, effective_from)
    values ((ns ->> 'id')::uuid, (ns ->> 'action_id')::uuid, ns ->> 'rule',
            coalesce(array(select (jsonb_array_elements_text(ns -> 'days'))::int), '{}'),
            (ns ->> 'per_week')::int, (ns ->> 'effective_from')::date);
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action_schedule', (ns ->> 'action_id')::uuid, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', (ns ->> 'effective_from')::date, review_id);
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'action_changes', '[]'::jsonb)) loop
    update public.actions
       set min_label = coalesce(item ->> 'min_label', min_label),
           min_minutes = (item ->> 'min_minutes')::int,
           min_count = (item ->> 'min_count')::int
     where id = (item ->> 'action_id')::uuid;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action', (item ->> 'action_id')::uuid, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', current_date, review_id);
  end loop;

  if payload ? 'week_plan' then
    insert into public.week_plans (id, week_start, available_minutes, planned_minutes, saved_at)
    values ((payload -> 'week_plan' ->> 'id')::uuid,
            (payload -> 'week_plan' ->> 'week_start')::date,
            coalesce((payload -> 'week_plan' ->> 'available_minutes')::int, 0),
            coalesce((payload -> 'week_plan' ->> 'planned_minutes')::int, 0),
            now())
    on conflict (user_id, week_start) do update
      set available_minutes = excluded.available_minutes,
          planned_minutes = excluded.planned_minutes,
          saved_at = now();
  end if;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'sessions', '[]'::jsonb)) loop
    insert into public.sessions (id, action_id, week_start, slot, date, title, priority,
                                 planned_minutes, planned_count, status, origin)
    values ((item ->> 'id')::uuid, (item ->> 'action_id')::uuid, (item ->> 'week_start')::date,
            coalesce((item ->> 'slot')::int, 0), (item ->> 'date')::date, item ->> 'title',
            coalesce((item ->> 'priority')::boolean, false),
            coalesce((item ->> 'planned_minutes')::int, 0), (item ->> 'planned_count')::int,
            'planned', coalesce(item ->> 'origin', 'scheduled'))
    on conflict (user_id, action_id, week_start, origin, slot)
    do update set date = excluded.date,
                  planned_minutes = excluded.planned_minutes,
                  planned_count = excluded.planned_count
      where public.sessions.status = 'planned';
  end loop;

  return review_id;
end;
$$;

grant execute on function public.complete_weekly_review(jsonb) to authenticated;

-- ---------- Private storage for photos and recordings (used in a later phase) ----------
insert into storage.buckets (id, name, public)
values ('attachments', 'attachments', false)
on conflict (id) do nothing;

create policy "attachments_owner_read" on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "attachments_owner_write" on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "attachments_owner_delete" on storage.objects for delete to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);

-- ======================================================================
-- 20261019000000_goal_breakdown.sql
-- ======================================================================
-- Goal breakdown: each goal flows 6 months → 3 months → months → weeks → daily tasks.
-- The 6-month level is the goal itself; plan_steps holds the levels below it.
-- Daily tasks are ordinary actions (with schedules) linked to the step they were planned in,
-- so they show up on Today exactly like every other action.

create table public.plan_steps (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  plan_id uuid not null references public.plans(id) on delete cascade,
  parent_id uuid references public.plan_steps(id) on delete cascade,
  level text not null check (level in ('quarter', 'month', 'week')),
  idx int not null default 0,
  title text not null,
  start_date date not null,
  end_date date not null,
  target_value numeric,
  target_note text not null default '',
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date >= start_date)
);
create index plan_steps_by_goal on public.plan_steps (user_id, goal_id, level, start_date);

create trigger plan_steps_touch before update on public.plan_steps
  for each row execute function public.touch_updated_at();

alter table public.plan_steps enable row level security;
create policy plan_steps_owner on public.plan_steps for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

alter table public.actions
  add column step_id uuid references public.plan_steps(id) on delete set null;

-- ======================================================================
-- 20261021000000_reminders_and_cues.sql
-- ======================================================================
-- Reminders and habit cues.
-- * actions.cue: an "after ___, at ___" habit cue shown with the task.
-- * profiles: morning reminder time, evening "streak saver" switch, and a secret
--   token for the read-only calendar feed (supabase/functions/calendar).
-- * push_subscriptions: one row per browser/phone that turned on reminders.
--   The send-reminders Edge Function reads these with the service role.
-- Safe to run more than once.

alter table public.actions add column if not exists cue text not null default '';

alter table public.profiles add column if not exists reminder_time time not null default '08:00';
alter table public.profiles add column if not exists evening_reminder boolean not null default true;
alter table public.profiles add column if not exists calendar_token uuid not null default gen_random_uuid();

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_calendar_token_key' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles add constraint profiles_calendar_token_key unique (calendar_token);
  end if;
end;
$$;

create table if not exists public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  user_agent text,
  created_at timestamptz not null default now(),
  last_morning_on date,
  last_evening_on date
);
create index if not exists push_subscriptions_by_user on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'push_subscriptions' and policyname = 'push_subscriptions_owner'
  ) then
    create policy push_subscriptions_owner on public.push_subscriptions for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

-- ======================================================================
-- 20261025000000_review_overhaul.sql
-- ======================================================================
-- Review overhaul: reviews remember more, and the review transaction can pause a task
-- or take a task out of next week.
-- * reviews.commitment_kept: did last review's "change next" happen? (yes / partly / no)
-- * reviews.goal_results: how each week, month, 3-month or plan goal turned out
-- * reviews.goal_decisions: 3-month checkpoint keep / adjust / drop per goal
-- * reviews.carry_forward: plan retrospective, what carries into the next plan
-- * reviews.minutes_planned / minutes_done: the time picture of the period
-- * complete_weekly_review: a schedule change with no new schedule pauses the task;
--   sessions may arrive with a status ('moved' = taken out of the week in the review);
--   week_plan is optional (month, 3-month and plan reviews don't plan a week).
-- Safe to run more than once.

alter table public.reviews add column if not exists commitment_kept text;
alter table public.reviews add column if not exists goal_results jsonb not null default '[]'::jsonb;
alter table public.reviews add column if not exists goal_decisions jsonb not null default '[]'::jsonb;
alter table public.reviews add column if not exists carry_forward text not null default '';
alter table public.reviews add column if not exists minutes_planned int not null default 0;
alter table public.reviews add column if not exists minutes_done int not null default 0;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'reviews_commitment_kept_check' and conrelid = 'public.reviews'::regclass
  ) then
    alter table public.reviews add constraint reviews_commitment_kept_check
      check (commitment_kept is null or commitment_kept in ('yes', 'partly', 'no'));
  end if;
end;
$$;

create or replace function public.complete_weekly_review(payload jsonb)
returns uuid
language plpgsql
security invoker
as $$
declare
  r jsonb := payload -> 'review';
  review_id uuid := coalesce((r ->> 'id')::uuid, gen_random_uuid());
  item jsonb;
  ns jsonb;
  changed_action uuid;
  effective date;
begin
  insert into public.reviews (id, kind, period_start, period_end, status, went_well, got_in_way,
                              change_next, obstacles, actions_done, actions_planned, completed_at,
                              commitment_kept, goal_results, goal_decisions, carry_forward,
                              minutes_planned, minutes_done)
  values (
    review_id,
    r ->> 'kind',
    (r ->> 'period_start')::date,
    (r ->> 'period_end')::date,
    'done',
    coalesce(r ->> 'went_well', ''),
    coalesce(r ->> 'got_in_way', ''),
    coalesce(r ->> 'change_next', ''),
    coalesce(array(select jsonb_array_elements_text(r -> 'obstacles')), '{}'),
    coalesce((r ->> 'actions_done')::numeric, 0),
    coalesce((r ->> 'actions_planned')::int, 0),
    now(),
    nullif(r ->> 'commitment_kept', ''),
    coalesce(r -> 'goal_results', '[]'::jsonb),
    coalesce(r -> 'goal_decisions', '[]'::jsonb),
    coalesce(r ->> 'carry_forward', ''),
    coalesce((r ->> 'minutes_planned')::int, 0),
    coalesce((r ->> 'minutes_done')::int, 0)
  );

  for item in select * from jsonb_array_elements(coalesce(payload -> 'measurements', '[]'::jsonb)) loop
    insert into public.measurements (id, type_id, value, measured_on, source, note)
    values ((item ->> 'id')::uuid, (item ->> 'type_id')::uuid, (item ->> 'value')::numeric,
            (item ->> 'measured_on')::date, 'manual', coalesce(item ->> 'note', ''));
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'schedule_changes', '[]'::jsonb)) loop
    update public.action_schedules
       set effective_to = (item ->> 'end_on')::date
     where id = (item ->> 'end_schedule_id')::uuid;
    ns := item -> 'new_schedule';
    changed_action := coalesce((ns ->> 'action_id')::uuid, (item ->> 'action_id')::uuid);
    effective := coalesce((ns ->> 'effective_from')::date, (item ->> 'end_on')::date + 1);
    -- No new schedule = the task is paused from the day after end_on.
    if ns is not null and jsonb_typeof(ns) = 'object' then
      insert into public.action_schedules (id, action_id, rule, days, per_week, effective_from)
      values ((ns ->> 'id')::uuid, (ns ->> 'action_id')::uuid, ns ->> 'rule',
              coalesce(array(select (jsonb_array_elements_text(ns -> 'days'))::int), '{}'),
              (ns ->> 'per_week')::int, (ns ->> 'effective_from')::date);
    end if;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action_schedule', changed_action, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', effective, review_id);
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'action_changes', '[]'::jsonb)) loop
    update public.actions
       set min_label = coalesce(item ->> 'min_label', min_label),
           min_minutes = (item ->> 'min_minutes')::int,
           min_count = (item ->> 'min_count')::int
     where id = (item ->> 'action_id')::uuid;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action', (item ->> 'action_id')::uuid, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', current_date, review_id);
  end loop;

  if payload ? 'week_plan' and jsonb_typeof(payload -> 'week_plan') = 'object' then
    insert into public.week_plans (id, week_start, available_minutes, planned_minutes, saved_at)
    values ((payload -> 'week_plan' ->> 'id')::uuid,
            (payload -> 'week_plan' ->> 'week_start')::date,
            coalesce((payload -> 'week_plan' ->> 'available_minutes')::int, 0),
            coalesce((payload -> 'week_plan' ->> 'planned_minutes')::int, 0),
            now())
    on conflict (user_id, week_start) do update
      set available_minutes = excluded.available_minutes,
          planned_minutes = excluded.planned_minutes,
          saved_at = now();
  end if;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'sessions', '[]'::jsonb)) loop
    insert into public.sessions (id, action_id, week_start, slot, date, title, priority,
                                 planned_minutes, planned_count, status, origin, note)
    values ((item ->> 'id')::uuid, (item ->> 'action_id')::uuid, (item ->> 'week_start')::date,
            coalesce((item ->> 'slot')::int, 0), (item ->> 'date')::date, item ->> 'title',
            coalesce((item ->> 'priority')::boolean, false),
            coalesce((item ->> 'planned_minutes')::int, 0), (item ->> 'planned_count')::int,
            case when item ->> 'status' = 'moved' then 'moved' else 'planned' end,
            coalesce(item ->> 'origin', 'scheduled'), coalesce(item ->> 'note', ''))
    on conflict (user_id, action_id, week_start, origin, slot)
    do update set date = excluded.date,
                  planned_minutes = excluded.planned_minutes,
                  planned_count = excluded.planned_count,
                  status = excluded.status,
                  note = case when excluded.status = 'moved' then excluded.note else public.sessions.note end
      where public.sessions.status = 'planned';
  end loop;

  return review_id;
end;
$$;

grant execute on function public.complete_weekly_review(jsonb) to authenticated;

-- ======================================================================
-- 20261026000000_goal_backlog.sql
-- ======================================================================
-- Goal backlog: ideas for goals, ordered by importance, Kanban style. Safe to run more than once.
--   backlog   → written down, waiting, in order of importance (rank: lower = more important)
--   selected  → "Selected for next commitment" (the app keeps this to 3)
--   started   → became a goal (goal_id points at it)
--   discarded → let go (kept so it can be restored)

create table if not exists public.goal_ideas (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  title text not null check (length(trim(title)) > 0),
  note text not null default '',
  status text not null default 'backlog' check (status in ('backlog', 'selected', 'started', 'discarded')),
  rank double precision not null default 0,
  goal_id uuid references public.goals(id) on delete set null,
  created_at timestamptz not null default now(),
  selected_at timestamptz,
  started_at timestamptz,
  updated_at timestamptz not null default now()
);
create index if not exists goal_ideas_by_status on public.goal_ideas (user_id, status, rank);

drop trigger if exists goal_ideas_touch on public.goal_ideas;
create trigger goal_ideas_touch before update on public.goal_ideas
  for each row execute function public.touch_updated_at();

alter table public.goal_ideas enable row level security;
drop policy if exists goal_ideas_owner on public.goal_ideas;
create policy goal_ideas_owner on public.goal_ideas for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ======================================================================
-- 20261027000000_completed_goals_and_readiness.sql
-- ======================================================================
-- Completed goals and backlog entry requirements. Safe to run more than once.
--   goals.completed_at / completion_note: a finished goal moves to Completed (its history is kept).
--   goal_ideas.done_means: what done looks like; with the why (note) it's needed to select an idea.

alter table public.goals add column if not exists completed_at timestamptz;
alter table public.goals add column if not exists completion_note text not null default '';
alter table public.goal_ideas add column if not exists done_means text not null default '';

-- ======================================================================
-- 20261028000000_idea_prep.sql
-- ======================================================================
-- Prepare, then commit: a selected idea keeps its prepared plan (chain notes, first daily task,
-- number target) until you commit it as a goal. Safe to run more than once.
alter table public.goal_ideas add column if not exists prep jsonb not null default '{}'::jsonb;

-- ======================================================================
-- 20261029000000_batches_and_own_clocks.sql
-- ======================================================================
-- Batches and own clocks. A plan is either a batch (shared by several goals; a goal can join
-- part-way through) or a goal's own clock (solo: one goal, starting the day it was committed).
-- Safe to run more than once.
alter table public.plans add column if not exists solo boolean not null default false;

-- ======================================================================
-- 20261030000000_attachments.sql
-- ======================================================================
-- Photos and other files on logged tasks. The files live in the private "attachments" storage
-- bucket (created in the initial schema, one folder per user); this table says which task each
-- file belongs to. Safe to run more than once.

create table if not exists public.attachments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  session_id uuid not null references public.sessions(id) on delete cascade,
  action_id uuid references public.actions(id) on delete set null,
  path text not null,
  name text not null default '',
  mime_type text not null default '',
  size_bytes bigint not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists attachments_session_idx on public.attachments (session_id);
create index if not exists attachments_action_idx on public.attachments (action_id);

alter table public.attachments enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'attachments' and policyname = 'attachments_owner') then
    create policy attachments_owner on public.attachments for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

-- The bucket and its owner-only policies, in case the initial schema's storage section was skipped.
insert into storage.buckets (id, name, public)
values ('attachments', 'attachments', false)
on conflict (id) do nothing;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'attachments_owner_read') then
    create policy "attachments_owner_read" on storage.objects for select to authenticated
      using (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'attachments_owner_write') then
    create policy "attachments_owner_write" on storage.objects for insert to authenticated
      with check (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'attachments_owner_delete') then
    create policy "attachments_owner_delete" on storage.objects for delete to authenticated
      using (bucket_id = 'attachments' and (storage.foldername(name))[1] = auth.uid()::text);
  end if;
end;
$$;

-- ======================================================================
-- 20261031000000_connected_goals.sql
-- ======================================================================
-- Connected goals and shared tasks. Safe to run more than once.
--  * goal_links: two goals you connected by hand (goals that share a task are connected without a row).
--  * actions.kind gains 'measure' (logging it records a number, e.g. the day's weight) and
--    'photo' (logging it takes a photo).
--  * actions.measurement_type_id: the measurement a measure task records.
-- A task already belongs to any number of goals through action_goals, so sharing needs no change there.

create table if not exists public.goal_links (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  goal_a uuid not null references public.goals(id) on delete cascade,
  goal_b uuid not null references public.goals(id) on delete cascade,
  note text not null default '',
  created_at timestamptz not null default now(),
  check (goal_a <> goal_b)
);

-- One link per pair, whichever way round it was made.
create unique index if not exists goal_links_pair_idx
  on public.goal_links (user_id, least(goal_a, goal_b), greatest(goal_a, goal_b));

alter table public.goal_links enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'goal_links' and policyname = 'goal_links_owner') then
    create policy goal_links_owner on public.goal_links for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

alter table public.actions drop constraint if exists actions_kind_check;
alter table public.actions add constraint actions_kind_check
  check (kind in ('check', 'count', 'minutes', 'workout', 'study', 'measure', 'photo'));

alter table public.actions add column if not exists measurement_type_id uuid
  references public.measurement_types(id) on delete set null;

-- ======================================================================
-- 20261101000000_goal_groups.sql
-- ======================================================================
-- Goal groups: named groups of goals made by dragging one goal onto another, like phone folders.
-- A goal is in one group at most (goals.group_id). Safe to run more than once.
-- Connections made earlier (goal_links) are turned into groups by the app the next time it opens.

create table if not exists public.goal_groups (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  created_at timestamptz not null default now()
);

alter table public.goal_groups enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'goal_groups' and policyname = 'goal_groups_owner') then
    create policy goal_groups_owner on public.goal_groups for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

alter table public.goals add column if not exists group_id uuid references public.goal_groups(id) on delete set null;
create index if not exists goals_group_idx on public.goals (group_id);

-- ======================================================================
-- 20261102000000_task_details.sql
-- ======================================================================
-- Task details: what a daily task involves (a workout's exercises, sets and reps), shown when you
-- log it. Safe to run more than once.
alter table public.actions add column if not exists details text not null default '';

-- ======================================================================
-- 20261103000000_measure_on_today.sql
-- ======================================================================
-- Which measurements show in Today's numbers. Null = the default (on for a goal's main number).
alter table public.measurement_types add column if not exists on_today boolean;

-- ======================================================================
-- 20261104000000_workout_plans.sql
-- ======================================================================
-- A workout task's plan: each exercise with sets, a rep range, a target weight and rest.
alter table public.actions add column if not exists workout_plan jsonb;

-- ======================================================================
-- 20261105000000_group_outcomes.sql
-- ======================================================================
-- Group outcomes and "starts after". Safe to run more than once.
--  * goal_groups.outcome: what the group's goals add up to (e.g. "Qualified for AI product and
--    governance work"). The group card shows it with one roll-up progress bar.
--  * goals.after_goal_id: this goal starts after that one is complete ("Up next" until then,
--    and it doesn't count as behind while it waits).
-- A goal's own "finish by" date uses the existing goals.target_date column.

alter table public.goal_groups add column if not exists outcome text not null default '';
alter table public.goals add column if not exists after_goal_id uuid references public.goals(id) on delete set null;
create index if not exists goals_after_idx on public.goals (after_goal_id);

-- ======================================================================
-- 20261106000000_goal_start_dates.sql
-- ======================================================================
-- A goal's own start date (set on the roadmap or in the goal's edit sheet). Safe to run more than once.
-- Empty means it starts with its window (or when the goal it starts after is complete).
alter table public.goals add column if not exists start_date date;

-- ======================================================================
-- 20261107000000_review_fixes.sql
-- ======================================================================
-- Review fixes and the "Then vs now" page.
-- * reviews.plan_id: which window (batch or own clock) a month, 3-month or retrospective review
--   belongs to. Without it two own clocks that started the same day shared one review.
-- * goals.reflection: your own words about a goal, written on the Then vs now page.
-- * measurements: one reading per measurement per day. The weekly review used to add a second
--   reading for a day that already had one; duplicates are merged (the latest wins) and a unique
--   index stops it happening again.
-- * complete_weekly_review: records plan_id, upserts measurements instead of inserting blindly, and
--   dates "minimum version" changes from the review's period end (the app did; the database used
--   the current date).
-- Safe to run more than once.

alter table public.reviews add column if not exists plan_id uuid references public.plans(id) on delete cascade;
create index if not exists reviews_by_plan on public.reviews (user_id, plan_id, kind, period_start);

alter table public.goals add column if not exists reflection text not null default '';

-- Merge duplicate readings: keep the most recent row for each (user, type, day).
delete from public.measurements m
 using public.measurements newer
 where newer.user_id = m.user_id
   and newer.type_id = m.type_id
   and newer.measured_on = m.measured_on
   and (newer.created_at > m.created_at or (newer.created_at = m.created_at and newer.id > m.id));

create unique index if not exists measurements_one_per_day on public.measurements (user_id, type_id, measured_on);

create or replace function public.complete_weekly_review(payload jsonb)
returns uuid
language plpgsql
security invoker
as $$
declare
  r jsonb := payload -> 'review';
  review_id uuid := coalesce((r ->> 'id')::uuid, gen_random_uuid());
  item jsonb;
  ns jsonb;
  changed_action uuid;
  effective date;
begin
  insert into public.reviews (id, kind, plan_id, period_start, period_end, status, went_well, got_in_way,
                              change_next, obstacles, actions_done, actions_planned, completed_at,
                              commitment_kept, goal_results, goal_decisions, carry_forward,
                              minutes_planned, minutes_done)
  values (
    review_id,
    r ->> 'kind',
    (r ->> 'plan_id')::uuid,
    (r ->> 'period_start')::date,
    (r ->> 'period_end')::date,
    'done',
    coalesce(r ->> 'went_well', ''),
    coalesce(r ->> 'got_in_way', ''),
    coalesce(r ->> 'change_next', ''),
    coalesce(array(select jsonb_array_elements_text(r -> 'obstacles')), '{}'),
    coalesce((r ->> 'actions_done')::numeric, 0),
    coalesce((r ->> 'actions_planned')::int, 0),
    now(),
    nullif(r ->> 'commitment_kept', ''),
    coalesce(r -> 'goal_results', '[]'::jsonb),
    coalesce(r -> 'goal_decisions', '[]'::jsonb),
    coalesce(r ->> 'carry_forward', ''),
    coalesce((r ->> 'minutes_planned')::int, 0),
    coalesce((r ->> 'minutes_done')::int, 0)
  );

  for item in select * from jsonb_array_elements(coalesce(payload -> 'measurements', '[]'::jsonb)) loop
    insert into public.measurements (id, type_id, value, measured_on, source, note)
    values ((item ->> 'id')::uuid, (item ->> 'type_id')::uuid, (item ->> 'value')::numeric,
            (item ->> 'measured_on')::date, coalesce(item ->> 'source', 'manual'), coalesce(item ->> 'note', ''))
    on conflict (user_id, type_id, measured_on)
    do update set value = excluded.value, source = excluded.source, note = excluded.note;
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'schedule_changes', '[]'::jsonb)) loop
    update public.action_schedules
       set effective_to = (item ->> 'end_on')::date
     where id = (item ->> 'end_schedule_id')::uuid;
    ns := item -> 'new_schedule';
    changed_action := coalesce((ns ->> 'action_id')::uuid, (item ->> 'action_id')::uuid);
    effective := coalesce((ns ->> 'effective_from')::date, (item ->> 'end_on')::date + 1);
    -- No new schedule = the task is paused from the day after end_on.
    if ns is not null and jsonb_typeof(ns) = 'object' then
      insert into public.action_schedules (id, action_id, rule, days, per_week, effective_from)
      values ((ns ->> 'id')::uuid, (ns ->> 'action_id')::uuid, ns ->> 'rule',
              coalesce(array(select (jsonb_array_elements_text(ns -> 'days'))::int), '{}'),
              (ns ->> 'per_week')::int, (ns ->> 'effective_from')::date);
    end if;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action_schedule', changed_action, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', effective, review_id);
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'action_changes', '[]'::jsonb)) loop
    update public.actions
       set min_label = coalesce(item ->> 'min_label', min_label),
           min_minutes = (item ->> 'min_minutes')::int,
           min_count = (item ->> 'min_count')::int
     where id = (item ->> 'action_id')::uuid;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action', (item ->> 'action_id')::uuid, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', coalesce((r ->> 'period_end')::date, current_date), review_id);
  end loop;

  if payload ? 'week_plan' and jsonb_typeof(payload -> 'week_plan') = 'object' then
    insert into public.week_plans (id, week_start, available_minutes, planned_minutes, saved_at)
    values ((payload -> 'week_plan' ->> 'id')::uuid,
            (payload -> 'week_plan' ->> 'week_start')::date,
            coalesce((payload -> 'week_plan' ->> 'available_minutes')::int, 0),
            coalesce((payload -> 'week_plan' ->> 'planned_minutes')::int, 0),
            now())
    on conflict (user_id, week_start) do update
      set available_minutes = excluded.available_minutes,
          planned_minutes = excluded.planned_minutes,
          saved_at = now();
  end if;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'sessions', '[]'::jsonb)) loop
    insert into public.sessions (id, action_id, week_start, slot, date, title, priority,
                                 planned_minutes, planned_count, status, origin, note)
    values ((item ->> 'id')::uuid, (item ->> 'action_id')::uuid, (item ->> 'week_start')::date,
            coalesce((item ->> 'slot')::int, 0), (item ->> 'date')::date, item ->> 'title',
            coalesce((item ->> 'priority')::boolean, false),
            coalesce((item ->> 'planned_minutes')::int, 0), (item ->> 'planned_count')::int,
            case when item ->> 'status' = 'moved' then 'moved' else 'planned' end,
            coalesce(item ->> 'origin', 'scheduled'), coalesce(item ->> 'note', ''))
    on conflict (user_id, action_id, week_start, origin, slot)
    do update set date = excluded.date,
                  planned_minutes = excluded.planned_minutes,
                  planned_count = excluded.planned_count,
                  status = excluded.status,
                  note = case when excluded.status = 'moved' then excluded.note else public.sessions.note end
      where public.sessions.status = 'planned';
  end loop;

  return review_id;
end;
$$;

grant execute on function public.complete_weekly_review(jsonb) to authenticated;

-- ======================================================================
-- 20261108000000_one_window_per_goal.sql
-- ======================================================================
-- One way to say when a goal runs: a goal has its own start and finish, and belongs to one season
-- (the review calendar). Own clocks and "starts after" are folded into those dates.
-- * Each own clock's goals take the clock's start and finish as their own dates and join the season
--   that was running when the clock started (the latest season otherwise); the clock is archived.
--   A user with clocks and no season keeps the first clock as their season.
-- * A goal that "started after" another gets a start date instead: the day that goal was completed,
--   or the day after it is due to finish. The column is then dropped.
-- Safe to run more than once.

do $$
declare
  clock record;
  season record;
  gid uuid;
begin
  for clock in select * from public.plans where solo and archived_at is null loop
    select p.* into season from public.plans p
      where p.user_id = clock.user_id and not p.solo and p.archived_at is null
        and p.start_date <= clock.start_date and p.end_date >= clock.start_date
      order by p.start_date desc limit 1;
    if season.id is null then
      select p.* into season from public.plans p
        where p.user_id = clock.user_id and not p.solo and p.archived_at is null
        order by p.end_date desc limit 1;
    end if;
    if season.id is null then
      update public.plans set solo = false, name = 'My six months' where id = clock.id;
      continue;
    end if;
    for gid in select goal_id from public.plan_goals where plan_id = clock.id loop
      update public.goals set
        start_date = case when clock.start_date > season.start_date then clock.start_date else start_date end,
        target_date = case when type <> 'number' and clock.end_date < season.end_date and (target_date is null or target_date > clock.end_date) then clock.end_date else target_date end
      where id = gid;
      insert into public.plan_goals (user_id, plan_id, goal_id)
        select clock.user_id, season.id, gid
        where not exists (select 1 from public.plan_goals where plan_id = season.id and goal_id = gid);
      delete from public.plan_goals where plan_id = clock.id and goal_id = gid;
    end loop;
    update public.plans set archived_at = now() where id = clock.id;
  end loop;
end;
$$;

-- "Starts after" becomes a start date.
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'goals' and column_name = 'after_goal_id') then
    update public.goals g
       set start_date = greatest(
         coalesce(g.start_date, '0001-01-01'::date),
         coalesce(
           (b.completed_at at time zone 'UTC')::date,
           b.target_date + 1,
           (select min(p.end_date) + 1 from public.plan_goals pg join public.plans p on p.id = pg.plan_id where pg.goal_id = b.id and p.archived_at is null)
         )
       )
      from public.goals b
     where g.after_goal_id = b.id;
    alter table public.goals drop column after_goal_id;
  end if;
end;
$$;

-- A plain backlog: one ordered list. "Selected" ideas go back to the list (at the top, in order),
-- and the prepared plan saved on an idea is no longer needed (making a goal asks directly).
update public.goal_ideas set status = 'backlog', rank = rank - 1000000 where status = 'selected';
alter table public.goal_ideas drop constraint if exists goal_ideas_status_check;
alter table public.goal_ideas add constraint goal_ideas_status_check check (status in ('backlog', 'started', 'discarded'));
alter table public.goal_ideas drop column if exists prep;
alter table public.goal_ideas drop column if exists selected_at;

-- One decomposition vocabulary: this week's goal and milestones. Month and 3-month notes are kept
-- on their rows for history but the app no longer asks for them or shows them. Group outcomes go.
alter table public.goal_groups drop column if exists outcome;

-- ======================================================================
-- 20261109000000_odyssey_paths.sql
-- ======================================================================
-- Odyssey paths: the three (or so) five-year lives you could live, above the seasons. Each path has
-- a headline, a year-by-year sketch, four gauges you rate (resources, likability, confidence,
-- coherence) and the open questions a prototype would answer. Goals and backlog ideas point at a
-- path, so a path's progress is rolled up from real work: goals finished, goals running and their
-- pace, time logged. Safe to run more than once.

create table if not exists public.paths (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  name text not null default '',
  headline text not null default '',
  why text not null default '',
  color text not null default '#5B8CFF',
  rank int not null default 0,
  horizon_years int not null default 5,
  -- One line per year, in order.
  years jsonb not null default '[]'::jsonb,
  -- {"resources": 1..5, "likability": 1..5, "confidence": 1..5, "coherence": 1..5}
  gauges jsonb not null default '{}'::jsonb,
  -- [{"on": "2026-10-26", "gauges": {...}}, ...] every time you re-rate (the 3-month checkpoint asks)
  gauge_log jsonb not null default '[]'::jsonb,
  -- [{"id", "text", "answer": "", "answered_at": null}] the questions a prototype would answer
  questions jsonb not null default '[]'::jsonb,
  -- [{"on": "2027-04-24", "text": "..."}] what each season taught you about this path (the retrospective asks)
  notes jsonb not null default '[]'::jsonb,
  archived_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.paths enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'paths' and policyname = 'paths_owner') then
    create policy paths_owner on public.paths for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

alter table public.goals add column if not exists path_id uuid references public.paths(id) on delete set null;
alter table public.goal_ideas add column if not exists path_id uuid references public.paths(id) on delete set null;
create index if not exists goals_path_idx on public.goals (path_id);
create index if not exists goal_ideas_path_idx on public.goal_ideas (path_id);

-- ======================================================================
-- 20261110000000_prizes.sql
-- ======================================================================
-- Prizes: a treat on a date to hit, on finishing a goal, or on a group landing.
-- See packages/core/src/prizes.ts for the rules (you judge "done"; the app records when and compares with the date).

alter table public.milestones
  add column if not exists value numeric,
  add column if not exists prize text not null default '',
  add column if not exists prize_claimed_at timestamptz;

alter table public.goals
  add column if not exists prize text not null default '',
  add column if not exists prize_on_time text not null default '',
  add column if not exists target_date_at_set date,
  add column if not exists prize_claimed_at timestamptz,
  add column if not exists prize_on_time_claimed_at timestamptz;

alter table public.goal_groups
  add column if not exists prize text not null default '',
  add column if not exists prize_threshold numeric check (prize_threshold is null or (prize_threshold > 0 and prize_threshold <= 1)),
  add column if not exists prize_claimed_at timestamptz;

comment on column public.milestones.value is 'For a number goal: the reading that marks this date hit. A reading at or past it completes the milestone.';
comment on column public.goals.target_date_at_set is 'The target date the on-time bonus is judged against, fixed when the bonus was set.';
comment on column public.goal_groups.prize_threshold is 'Share of the group''s goals (0–1) that must finish for the group prize; null = 0.85.';

-- ======================================================================
-- 20261111000000_digests_and_experiments.sql
-- ======================================================================
-- Weekly digests to an accountability partner, a Sunday review reminder, and path experiments.

alter table public.profiles
  add column if not exists partner_email text,
  add column if not exists review_reminder boolean not null default true;

alter table public.reviews
  add column if not exists digest text not null default '',
  add column if not exists digest_sent_at timestamptz;

alter table public.goal_groups
  add column if not exists week_goal text not null default '',
  add column if not exists week_goal_for date;

alter table public.push_subscriptions
  add column if not exists last_review_on date;

-- Path experiments: a small, dated thing that answers one of a path's questions.
create table if not exists public.path_experiments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  path_id uuid not null references public.paths (id) on delete cascade,
  question_id text,
  title text not null,
  due_date date not null,
  note text not null default '',
  result text not null default '',
  completed_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists path_experiments_by_user on public.path_experiments (user_id);
alter table public.path_experiments enable row level security;
drop policy if exists "own path_experiments" on public.path_experiments;
create policy "own path_experiments" on public.path_experiments for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

comment on column public.reviews.digest is 'Weekly digest text, written by the app when the review is saved; send-digests mails it to profiles.partner_email.';

-- ======================================================================
-- 20261112000000_tallies.sql
-- ======================================================================
-- Tallies: a date to hit that is a running total of a count task
-- ("250 applications by Dec 15", counted from "Apply to 25 jobs").
-- Every log of the task adds its count to milestones.value's target; the date ticks itself off when it's reached.
-- See packages/core/src/tally.ts.

alter table public.milestones
  add column if not exists count_action_id uuid references public.actions(id) on delete set null;

create index if not exists milestones_count_action_idx on public.milestones (count_action_id) where count_action_id is not null;

comment on column public.milestones.count_action_id is 'The count task whose logged counts add up toward value. Null = a plain date (or, on a number goal, a reading to reach).';

-- ======================================================================
-- 20261113000000_goal_order.sql
-- ======================================================================
-- Your own order for goals and groups on the Goals page (drag a goal above or below another, or a group above another).
-- Null = not placed by hand yet; those sort after placed ones, in the app's usual order.

alter table public.goals add column if not exists sort_order integer;
alter table public.goal_groups add column if not exists sort_order integer;

comment on column public.goals.sort_order is 'Hand-set position among its siblings (its group, or the loose goals) on the Goals page. Null = not placed.';
comment on column public.goal_groups.sort_order is 'Hand-set position among groups on the Goals page. Null = not placed.';

-- ======================================================================
-- 20261114000000_backlog_selected.sql
-- ======================================================================
-- Selected for next: a second bucket in the backlog for ideas refined enough to commit (a why and what done looks like).
-- Kept as a timestamp on the idea; status stays 'backlog' so nothing else changes.

alter table public.goal_ideas add column if not exists shortlisted_at timestamptz;

comment on column public.goal_ideas.shortlisted_at is 'Set when the idea is moved to "Selected for next"; null = plain backlog. Ranks are kept per bucket.';

-- ======================================================================
-- 20261115000000_session_scheduled_on.sql
-- ======================================================================
-- Sessions remember the day their schedule put them on (scheduled_on).
--
-- Bug this fixes: moving a scheduled session to another day (Wednesday's workout to Thursday) made
-- the weekly top-up think Wednesday was missing, so it made a second copy there the next time the
-- app opened. With scheduled_on, a moved session still covers the day it was scheduled for.
--
-- Existing rows are left null on purpose: the app treats a null as "the day it's on", and repairs
-- this week's and coming weeks' moved sessions, and the extra copies the bug made, itself the next
-- time it opens (opsRepairMovedSessions in apps/web/src/data/ops.ts). Only the schedule knows which
-- day a moved session came from, so filling the column in here from `date` would hide the moves.
--
-- The weekly review's function is redefined unchanged except that it saves scheduled_on for the
-- sessions it plans. Safe to run twice.

alter table public.sessions add column if not exists scheduled_on date;

create or replace function public.complete_weekly_review(payload jsonb)
returns uuid
language plpgsql
security invoker
as $$
declare
  r jsonb := payload -> 'review';
  review_id uuid := coalesce((r ->> 'id')::uuid, gen_random_uuid());
  item jsonb;
  ns jsonb;
  changed_action uuid;
  effective date;
begin
  insert into public.reviews (id, kind, plan_id, period_start, period_end, status, went_well, got_in_way,
                              change_next, obstacles, actions_done, actions_planned, completed_at,
                              commitment_kept, goal_results, goal_decisions, carry_forward,
                              minutes_planned, minutes_done)
  values (
    review_id,
    r ->> 'kind',
    (r ->> 'plan_id')::uuid,
    (r ->> 'period_start')::date,
    (r ->> 'period_end')::date,
    'done',
    coalesce(r ->> 'went_well', ''),
    coalesce(r ->> 'got_in_way', ''),
    coalesce(r ->> 'change_next', ''),
    coalesce(array(select jsonb_array_elements_text(r -> 'obstacles')), '{}'),
    coalesce((r ->> 'actions_done')::numeric, 0),
    coalesce((r ->> 'actions_planned')::int, 0),
    now(),
    nullif(r ->> 'commitment_kept', ''),
    coalesce(r -> 'goal_results', '[]'::jsonb),
    coalesce(r -> 'goal_decisions', '[]'::jsonb),
    coalesce(r ->> 'carry_forward', ''),
    coalesce((r ->> 'minutes_planned')::int, 0),
    coalesce((r ->> 'minutes_done')::int, 0)
  );

  for item in select * from jsonb_array_elements(coalesce(payload -> 'measurements', '[]'::jsonb)) loop
    insert into public.measurements (id, type_id, value, measured_on, source, note)
    values ((item ->> 'id')::uuid, (item ->> 'type_id')::uuid, (item ->> 'value')::numeric,
            (item ->> 'measured_on')::date, coalesce(item ->> 'source', 'manual'), coalesce(item ->> 'note', ''))
    on conflict (user_id, type_id, measured_on)
    do update set value = excluded.value, source = excluded.source, note = excluded.note;
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'schedule_changes', '[]'::jsonb)) loop
    update public.action_schedules
       set effective_to = (item ->> 'end_on')::date
     where id = (item ->> 'end_schedule_id')::uuid;
    ns := item -> 'new_schedule';
    changed_action := coalesce((ns ->> 'action_id')::uuid, (item ->> 'action_id')::uuid);
    effective := coalesce((ns ->> 'effective_from')::date, (item ->> 'end_on')::date + 1);
    -- No new schedule = the task is paused from the day after end_on.
    if ns is not null and jsonb_typeof(ns) = 'object' then
      insert into public.action_schedules (id, action_id, rule, days, per_week, effective_from)
      values ((ns ->> 'id')::uuid, (ns ->> 'action_id')::uuid, ns ->> 'rule',
              coalesce(array(select (jsonb_array_elements_text(ns -> 'days'))::int), '{}'),
              (ns ->> 'per_week')::int, (ns ->> 'effective_from')::date);
    end if;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action_schedule', changed_action, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', effective, review_id);
  end loop;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'action_changes', '[]'::jsonb)) loop
    update public.actions
       set min_label = coalesce(item ->> 'min_label', min_label),
           min_minutes = (item ->> 'min_minutes')::int,
           min_count = (item ->> 'min_count')::int
     where id = (item ->> 'action_id')::uuid;
    insert into public.change_log (entity, entity_id, summary, old_value, new_value, effective_from, review_id)
    values ('action', (item ->> 'action_id')::uuid, item ->> 'summary',
            item -> 'old_value', item -> 'new_value', coalesce((r ->> 'period_end')::date, current_date), review_id);
  end loop;

  if payload ? 'week_plan' and jsonb_typeof(payload -> 'week_plan') = 'object' then
    insert into public.week_plans (id, week_start, available_minutes, planned_minutes, saved_at)
    values ((payload -> 'week_plan' ->> 'id')::uuid,
            (payload -> 'week_plan' ->> 'week_start')::date,
            coalesce((payload -> 'week_plan' ->> 'available_minutes')::int, 0),
            coalesce((payload -> 'week_plan' ->> 'planned_minutes')::int, 0),
            now())
    on conflict (user_id, week_start) do update
      set available_minutes = excluded.available_minutes,
          planned_minutes = excluded.planned_minutes,
          saved_at = now();
  end if;

  for item in select * from jsonb_array_elements(coalesce(payload -> 'sessions', '[]'::jsonb)) loop
    insert into public.sessions (id, action_id, week_start, slot, date, title, priority,
                                 planned_minutes, planned_count, status, origin, note, scheduled_on)
    values ((item ->> 'id')::uuid, (item ->> 'action_id')::uuid, (item ->> 'week_start')::date,
            coalesce((item ->> 'slot')::int, 0), (item ->> 'date')::date, item ->> 'title',
            coalesce((item ->> 'priority')::boolean, false),
            coalesce((item ->> 'planned_minutes')::int, 0), (item ->> 'planned_count')::int,
            case when item ->> 'status' = 'moved' then 'moved' else 'planned' end,
            coalesce(item ->> 'origin', 'scheduled'), coalesce(item ->> 'note', ''),
            (item ->> 'scheduled_on')::date)
    on conflict (user_id, action_id, week_start, origin, slot)
    do update set date = excluded.date,
                  planned_minutes = excluded.planned_minutes,
                  planned_count = excluded.planned_count,
                  status = excluded.status,
                  note = case when excluded.status = 'moved' then excluded.note else public.sessions.note end
      where public.sessions.status = 'planned';
  end loop;

  return review_id;
end;
$$;

grant execute on function public.complete_weekly_review(jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ======================================================================
-- 20261117000000_stretching.sql
-- ======================================================================
-- Stretching: a task type of its own, like workouts.
--
-- 1. actions.kind may be 'stretch'.
-- 2. actions.stretch_plan: the holds for that day (the Daily Eight and the day's focus slot), push
--    or easy, with how-to text. Shown when you open the task; nothing is timed.
-- 3. stretch_holds: each hold of a logged stretching session, ticked off, and whether it hurt.
--
-- Safe to run twice.

alter table public.actions drop constraint if exists actions_kind_check;
alter table public.actions add constraint actions_kind_check
  check (kind in ('check', 'count', 'minutes', 'workout', 'study', 'measure', 'photo', 'stretch'));

alter table public.actions add column if not exists stretch_plan jsonb;

create table if not exists public.stretch_holds (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  session_id uuid not null references public.sessions(id) on delete cascade,
  position int not null default 0,
  hold text not null default '',
  done boolean not null default false,
  pain boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists stretch_holds_session_idx on public.stretch_holds (session_id);

alter table public.stretch_holds enable row level security;
do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'stretch_holds' and policyname = 'stretch_holds_owner') then
    create policy stretch_holds_owner on public.stretch_holds for all to authenticated
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end;
$$;

notify pgrst, 'reload schema';

